package com.intellipolis.external;
import com.intellipolis.common.config.ExternalHttp;
import java.net.URI;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import java.util.stream.IntStream;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import org.springframework.web.util.UriComponentsBuilder;import tools.jackson.databind.JsonNode;
@Service public class ExternalDataService {
 private static final Map<String,String> SIDO=Map.of("서울특별시","110000","부산광역시","210000","인천광역시","220000","대구광역시","230000","광주광역시","240000","대전광역시","250000","울산광역시","260000");
 private final String publicKey,neisKey,seoulKey;private final RestClient http=ExternalHttp.create();private final Map<String,Integer> hospitalCounts=new HashMap<>();private volatile List<double[]> seoulStops;
 public ExternalDataService(@Value("${app.public-data.api-key:}")String p,@Value("${app.neis.api-key:}")String n,@Value("${app.seoul-data.api-key:}")String s){publicKey=p;neisKey=n;seoulKey=s;}
 public Map<String,Boolean> status(){return Map.of("publicData",!publicKey.isBlank(),"neis",!neisKey.isBlank(),"seoul",!seoulKey.isBlank());}
 public JsonNode hospitals(String sidoCode,String districtCode){require(publicKey,"공공데이터포털");return get(UriComponentsBuilder.fromUriString("https://apis.data.go.kr/B551182/hospInfoServicev2/getHospBasisList").queryParam("serviceKey",publicKey).queryParam("pageNo",1).queryParam("numOfRows",1000).queryParam("sidoCd",sidoCode).queryParam("sgguCd",districtCode).queryParam("_type","json").build().encode().toUri());}
 public synchronized int hospitalCount(String city,String district){require(publicKey,"공공데이터포털");String key=city+"/"+district;if(hospitalCounts.containsKey(key))return hospitalCounts.get(key);String sido=SIDO.get(city);if(sido==null)throw new ExternalDataException("지원하지 않는 시도입니다.");JsonNode first=hospitals(sido,"",1,1000).path("response").path("body");AtomicReference<String> sggu=new AtomicReference<>();findDistrict(first,district,sggu);int pages=(first.path("totalCount").asInt()+999)/1000;if(sggu.get()==null)IntStream.rangeClosed(2,pages).parallel().mapToObj(page->hospitals(sido,"",page,1000).path("response").path("body")).takeWhile(x->sggu.get()==null).forEach(x->findDistrict(x,district,sggu));if(sggu.get()==null)throw new ExternalDataException("의료기관 시군구 코드를 찾지 못했습니다.");int count=hospitals(sido,sggu.get(),1,1).path("response").path("body").path("totalCount").asInt();hospitalCounts.put(key,count);return count;}
 private void findDistrict(JsonNode body,String district,AtomicReference<String> found){for(JsonNode item:body.path("items").path("item"))if(district.equals(item.path("sgguCdNm").asText())){found.compareAndSet(null,item.path("sgguCd").asText());break;}}
 public synchronized List<double[]> seoulBusStops(){require(seoulKey,"서울 열린데이터광장");if(seoulStops!=null)return seoulStops;JsonNode first=seoulBusPage(1,1000);int total=first.path("list_total_count").asInt();List<double[]> result=Collections.synchronizedList(new ArrayList<>());addBusRows(first,result);IntStream.rangeClosed(1,(total-1)/1000).parallel().mapToObj(page->seoulBusPage(page*1000+1,(page+1)*1000)).forEach(data->addBusRows(data,result));return seoulStops=List.copyOf(result);}
 private JsonNode seoulBusPage(int start,int end){return get(URI.create("http://openapi.seoul.go.kr:8088/"+seoulKey+"/json/busStopLocationXyInfo/"+start+"/"+end+"/")).path("busStopLocationXyInfo");}
 private void addBusRows(JsonNode data,List<double[]> result){for(JsonNode row:data.path("row"))result.add(new double[]{row.path("XCRD").asDouble(),row.path("YCRD").asDouble()});}
 private JsonNode hospitals(String sido,String sggu,int page,int rows){return get(UriComponentsBuilder.fromUriString("https://apis.data.go.kr/B551182/hospInfoServicev2/getHospBasisList").queryParam("serviceKey",publicKey).queryParam("pageNo",page).queryParam("numOfRows",rows).queryParam("sidoCd",sido).queryParamIfPresent("sgguCd",Optional.ofNullable(sggu).filter(x->!x.isBlank())).queryParam("_type","json").build().encode().toUri());}
 public JsonNode air(String sido){require(publicKey,"공공데이터포털");return get(UriComponentsBuilder.fromUriString("https://apis.data.go.kr/B552584/ArpltnInforInqireSvc/getCtprvnRltmMesureDnsty").queryParam("serviceKey",publicKey).queryParam("returnType","json").queryParam("numOfRows",100).queryParam("pageNo",1).queryParam("sidoName",sido).queryParam("ver","1.0").build().encode().toUri());}
 public JsonNode schools(String officeCode,String district){require(neisKey,"나이스");return get(UriComponentsBuilder.fromUriString("https://open.neis.go.kr/hub/schoolInfo").queryParam("KEY",neisKey).queryParam("Type","json").queryParam("pIndex",1).queryParam("pSize",1000).queryParam("ATPT_OFCDC_SC_CODE",officeCode).queryParam("LCTN_SC_NM",district).build().encode().toUri());}
 private JsonNode get(URI uri){try{JsonNode body=http.get().uri(uri).retrieve().body(JsonNode.class);if(body==null)throw new ExternalDataException("외부 데이터 응답이 비어 있습니다.");return body;}catch(ExternalDataException e){throw e;}catch(Exception e){throw new ExternalDataException("외부 공공데이터 서버 호출에 실패했습니다.");}}
 private void require(String key,String name){if(key.isBlank())throw new ExternalDataException(name+" API 키가 설정되지 않았습니다.");}
}
